netstat -tulpn 2>/dev/null || ss -tulpn 2>/dev/null || python3 -c "import socket; 
for port in [8008, 11080, 8080, 80, 3000, 5000]:
    sock = socket.socket()
    sock.settimeout(0.1)
    result = sock.connect_ex(('127.0.0.1', port))
    if result == 0:
        print(f'Port {port} is open on localhost')
    sock.close()"

